contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes inputs that will be forwarded to c.transfer.
    // Note: we cannot inspect internals of the target caddress; we only observe whether the call reverted
    // by catching exceptions when invoking c.transfer. The property asserts that when c.transfer returns
    // (i.e., did not revert) it returns true. If it reverts, the revert boolean will be true.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // call c.transfer and observe whether it reverts
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false; // placeholder when reverted
        }

        // General rule: c.transfer never successfully returns false; if it returns (didn't revert) it must return true.
        // Expressed as: not(reverted) => ret == true
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

